                try{b.read();throw new AssertionError("Cross-scope capsule must fail authentication");}catch(java.security.GeneralSecurityException expected){test.yes(base.read().equals(code));}
                refused(()->BackupRecoveryKeyStore.scoped(f.context,"../qa_escape"),"RECOVERY_SCOPE_INVALID");
